    rstan                         ->  PyStan (httpstan / Stan-services)
    ---------------------------------------------------------------
    chains = 4                    ->  num_chains = 4
    iter = 2000, warmup = 1000    ->  num_warmup = 1000, num_samples = 1000
    thin = 2                      ->  num_thin = 2        (-> 500 kept / chain)
    seed = 1                      ->  random_seed = 1     (set in stan.build)
    save_warmup = FALSE           ->  save_warmup = False
    refresh = 200                 ->  refresh = 200
    control$adapt_delta   = 0.93  ->  delta = 0.93
    control$max_treedepth = 14    ->  max_depth = 14
    control$adapt_gamma   = 0.05  ->  gamma = 0.05
    control$adapt_kappa   = 0.75  ->  kappa = 0.75
    control$adapt_t0      = 10    ->  t0 = 10
    control$adapt_init_buffer =100-> init_buffer = 100
