    "N": N,
    "D": D,
    "X": train_X_mat,
    "P": P,
    "H": H,
    "y": train_y_vec,
    "jitter": jitter,
    "N_new": N_new,
    "X_new": test_X_mat,
    "H_new": H_new,
}
