# ----------------------------------------------------------------------
# 2. Stan model code
#    Functionally equivalent to the model embedded in gp_rstan.R.
#
#    Memory-efficiency optimisation (optional, per the task): in the
#    original model ``mu``, ``K`` and ``L_K`` were declared in a
#    ``transformed parameters`` block.  Stan stores every transformed
#    parameter for every draw, which here means an N x N (200 x 200)
#    matrix for K and another for L_K per draw -- roughly 1.3 GB for
#    4 chains x 500 draws.  They are instead computed as *local*
#    variables inside the ``model`` block (locals are not stored) and
#    ``L_K`` is recomputed inside ``generated quantities`` where it is
#    needed for the posterior-predictive draws.
#
#    This changes neither the log-density nor the RNG consumption
#    (transformed parameters / model-block locals do not draw random
#    numbers), so the posterior over (beta, alpha, rho, sigma) and the
#    generated quantity y_new are identical to the original model.
# ----------------------------------------------------------------------
stan_code = """
functions {
  matrix cov_ard_sqexp(matrix X, vector rho, real alpha, real jitter) {
    int N = rows(X);
    int D = cols(X);
    matrix[N, N] K;

    for (i in 1:N) {
      K[i, i] = square(alpha) + jitter;
      for (j in (i + 1):N) {
        real s = 0;
        for (d in 1:D) {
          real t = (X[i, d] - X[j, d]) / rho[d];
          s += t * t;
        }
        K[i, j] = square(alpha) * exp(-0.5 * s);
        K[j, i] = K[i, j];
      }
    }
    return K;
  }

  matrix cross_cov_ard(matrix X, matrix X_new, vector rho, real alpha) {
    int N = rows(X);
    int M = rows(X_new);
    int D = cols(X); // == cols(X_new)
    matrix[N, M] Kx;
    for (i in 1:N) {
      for (j in 1:M) {
        real s = 0;
        for (d in 1:D) {
          real t = (X[i, d] - X_new[j, d]) / rho[d];
          s += t * t;
        }
        Kx[i, j] = square(alpha) * exp(-0.5 * s);
      }
    }
    return Kx;
  }
}

data {
  int<lower=1> N;
  int<lower=1> D;
  matrix[N, D] X;
  int<lower=1> P;
  matrix[N, P] H;
  vector[N] y;
  real<lower=0> jitter;

  int<lower=0> N_new;
  matrix[N_new, D] X_new;
  matrix[N_new, P] H_new;
}

parameters {
  vector[P] beta;
  real<lower=0> alpha;
  vector<lower=0>[D] rho;
  real<lower=0> sigma;
}

model {
  // local variables (formerly transformed parameters) -- not stored per draw
  vector[N] mu = H * beta;
